\begin{aligned}
\sum_{k=1}^{n} (a_k + b_k) &= \sum_{k=1}^{n} a_k + \sum_{k=1}^{n} b_k \\
\sum_{k=1}^{n} c \cdot a_k &= c \cdot \sum_{k=1}^{n} a_k \\
\sum_{k=1}^{n} a_k &= \sum_{k=1}^{m} a_k + \sum_{k=m+1}^{n} a_k
\end{aligned}

\begin{aligned}
\sum_{k=1}^{n} a_k b_k &\neq \left(\sum_{k=1}^{n} a_k\right)\left(\sum_{k=1}^{n} b_k\right) \\
\sum_{k=1}^{n} a_k^2 &\neq \left(\sum_{k=1}^{n} a_k\right)^2 \\
\sum_{k=1}^{n} (a_k + 1) &\neq \sum_{k=1}^{n} a_k + 1
\end{aligned}
